SELECT  json_build_object('aggregate', json_build_object('count', COUNT(*), 'sum', json_build_object('id', sum("_root"."root.pg.id" ) ) ), 'nodes', coalesce(json_agg("root.f.nodes" ), '[]' ) ) AS "root" FROM  (SELECT  "_root.base"."id" AS "root.pg.id", row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.base"."title" AS "title"       ) AS "_e"      ) ) AS "root.f.nodes" FROM  (SELECT  *  FROM "public"."article"  WHERE (("public"."article"."id") <= (('5')::integer))     ) AS "_root.base"      ) AS "_root"
